import java.util.*;

class Twitter {
    private final Map<Integer, List<int[]>> tweets = new HashMap<>();
    private final Map<Integer, Set<Integer>> following = new HashMap<>();
    private int timestamp = 0;

    public Twitter() {
    }

    public void postTweet(int userId, int tweetId) {
        tweets.computeIfAbsent(userId, ignored -> new ArrayList<>())
                .add(new int[]{timestamp++, tweetId});
    }

    public List<Integer> getNewsFeed(int userId) {
        PriorityQueue<int[]> minHeap = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        addVisibleTweets(userId, minHeap);
        for (int followeeId : following.getOrDefault(userId, Collections.emptySet())) {
            addVisibleTweets(followeeId, minHeap);
        }

        List<int[]> newest = new ArrayList<>(minHeap);
        newest.sort((a, b) -> Integer.compare(b[0], a[0]));

        List<Integer> feed = new ArrayList<>();
        for (int[] tweet : newest) {
            feed.add(tweet[1]);
        }
        return feed;
    }

    private void addVisibleTweets(int userId, PriorityQueue<int[]> minHeap) {
        for (int[] tweet : tweets.getOrDefault(userId, Collections.emptyList())) {
            minHeap.offer(tweet);
            if (minHeap.size() > 10) {
                minHeap.poll();
            }
        }
    }

    public void follow(int followerId, int followeeId) {
        if (followerId == followeeId) {
            return;
        }
        following.computeIfAbsent(followerId, ignored -> new HashSet<>()).add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> followees = following.get(followerId);
        if (followees != null) {
            followees.remove(followeeId);
        }
    }
}

import java.util.*;

class Twitter {
    private static class Tweet {
        int id;
        int timestamp;
        Tweet next;

        Tweet(int id, int timestamp) {
            this.id = id;
            this.timestamp = timestamp;
        }
    }

    private final Map<Integer, Tweet> tweetHeads = new HashMap<>();
    private final Map<Integer, Set<Integer>> following = new HashMap<>();
    private int timestamp = 0;

    public Twitter() {
    }

    public void postTweet(int userId, int tweetId) {
        Tweet tweet = new Tweet(tweetId, timestamp++);
        tweet.next = tweetHeads.get(userId);
        tweetHeads.put(userId, tweet);
    }

    public List<Integer> getNewsFeed(int userId) {
        PriorityQueue<Tweet> maxHeap = new PriorityQueue<>((a, b) -> Integer.compare(b.timestamp, a.timestamp));
        Tweet ownHead = tweetHeads.get(userId);
        if (ownHead != null) {
            maxHeap.offer(ownHead);
        }
        for (int followeeId : following.getOrDefault(userId, Collections.emptySet())) {
            Tweet followeeHead = tweetHeads.get(followeeId);
            if (followeeHead != null) {
                maxHeap.offer(followeeHead);
            }
        }

        List<Integer> feed = new ArrayList<>();
        while (!maxHeap.isEmpty() && feed.size() < 10) {
            Tweet newest = maxHeap.poll();
            feed.add(newest.id);
            if (newest.next != null) {
                maxHeap.offer(newest.next);
            }
        }
        return feed;
    }

    public void follow(int followerId, int followeeId) {
        if (followerId == followeeId) {
            return;
        }
        following.computeIfAbsent(followerId, ignored -> new HashSet<>()).add(followeeId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> followees = following.get(followerId);
        if (followees != null) {
            followees.remove(followeeId);
        }
    }
}

