import java.util.*;

class Twitter {
    private static class Tweet {
        int userId;
        int tweetId;

        Tweet(int userId, int tweetId) {
            this.userId = userId;
            this.tweetId = tweetId;
        }
    }

    private final List<Tweet> timeline = new ArrayList<>();
    private final Map<Integer, Set<Integer>> following = new HashMap<>();
    private final Map<Integer, Set<Integer>> followers = new HashMap<>();
    private final Map<Integer, Deque<Tweet>> feedCache = new HashMap<>();

    public Twitter() {
    }

    public void postTweet(int userId, int tweetId) {
        Tweet tweet = new Tweet(userId, tweetId);
        timeline.add(tweet);
        pushToCachedFeed(userId, tweet);
        for (int followerId : followers.getOrDefault(userId, Collections.emptySet())) {
            pushToCachedFeed(followerId, tweet);
        }
    }

    public List<Integer> getNewsFeed(int userId) {
        List<Integer> feed = new ArrayList<>();
        for (Tweet tweet : feedCache.getOrDefault(userId, new ArrayDeque<>())) {
            feed.add(tweet.tweetId);
            if (feed.size() == 10) {
                break;
            }
        }
        return feed;
    }

    public void follow(int followerId, int followeeId) {
        if (followerId == followeeId) {
            return;
        }
        boolean added = following.computeIfAbsent(followerId, ignored -> new HashSet<>()).add(followeeId);
        if (!added) {
            return;
        }
        followers.computeIfAbsent(followeeId, ignored -> new HashSet<>()).add(followerId);
        rebuildFeed(followerId);
    }

    public void unfollow(int followerId, int followeeId) {
        Set<Integer> followees = following.get(followerId);
        if (followees == null || !followees.remove(followeeId)) {
            return;
        }
        Set<Integer> followerSet = followers.get(followeeId);
        if (followerSet != null) {
            followerSet.remove(followerId);
        }
        rebuildFeed(followerId);
    }

    private void pushToCachedFeed(int userId, Tweet tweet) {
        Deque<Tweet> feed = feedCache.computeIfAbsent(userId, ignored -> new ArrayDeque<>());
        feed.addFirst(tweet);
        while (feed.size() > 10) {
            feed.removeLast();
        }
    }

    private void rebuildFeed(int userId) {
        Deque<Tweet> feed = new ArrayDeque<>();
        Set<Integer> followees = following.getOrDefault(userId, Collections.emptySet());
        for (int i = timeline.size() - 1; i >= 0 && feed.size() < 10; i--) {
            Tweet tweet = timeline.get(i);
            if (tweet.userId == userId || followees.contains(tweet.userId)) {
                feed.addLast(tweet);
            }
        }
        feedCache.put(userId, feed);
    }
}
